//! The golden vectors in vectors/bz_vectors.json, generated by the Python
//! reference: event times within one second, displayed values exact.

use bz::{Instant, Reading, SolarDuration};
use serde_json::Value;

const VECTORS: &str = include_str!("../vectors/bz_vectors.json");

#[test]
fn every_vector_passes() {
    let file: Value = serde_json::from_str(VECTORS).unwrap();
    let vectors = file["vectors"].as_array().unwrap();
    assert!(!vectors.is_empty());
    for v in vectors {
        let name = v["name"].as_str().unwrap();
        let t = Instant::parse_rfc3339(v["utc"].as_str().unwrap()).unwrap();
        let r = Reading::at(t, v["lat"].as_f64().unwrap(), v["lon"].as_f64().unwrap());
        let e = &v["expected"];
        let day = &r.day;

        assert_eq!(day.date.to_string(), e["bz_date"], "{name}: bz_date");
        instant_within(name, "solar_noon_utc", day.noon, &e["solar_noon_utc"]);
        instant_within(
            name,
            "solar_midnight_start_utc",
            day.midnight_start,
            &e["solar_midnight_start_utc"],
        );
        instant_within(
            name,
            "solar_midnight_end_utc",
            day.midnight_end,
            &e["solar_midnight_end_utc"],
        );
        assert_eq!(r.anchor.name(), e["anchor"], "{name}: anchor");
        assert!(
            (r.offset_s - e["offset_s"].as_f64().unwrap()).abs() <= 1.0,
            "{name}: offset_s {}",
            r.offset_s
        );
        assert_eq!(
            r.display_offset_ks(),
            e["display_offset_ks"].as_f64().unwrap(),
            "{name}: display_offset_ks"
        );

        if let Some(polar) = e["polar"].as_str() {
            assert_eq!(r.polar().map(|p| p.name()), Some(polar), "{name}: polar");
            assert!(
                r.span().is_none() && r.quarter().is_none(),
                "{name}: polar has no span"
            );
            continue;
        }
        instant_within(
            name,
            "sunrise_utc",
            day.sunrise().unwrap(),
            &e["sunrise_utc"],
        );
        instant_within(name, "sunset_utc", day.sunset().unwrap(), &e["sunset_utc"]);
        seconds_within(
            name,
            "tagbogen_s",
            day.tagbogen_s().unwrap(),
            &e["tagbogen_s"],
        );
        if let Some(half_night) = e["half_night_s"].as_f64() {
            seconds_within(
                name,
                "half_night_s",
                r.span_s().unwrap() * 100.0,
                &Value::from(half_night),
            );
        }
        let span = r.span().unwrap();
        assert!(
            (span - e["span"].as_f64().unwrap()).abs() <= 0.001,
            "{name}: span {span}"
        );
        assert_eq!(
            r.display_span().unwrap(),
            e["display_span"].as_i64().unwrap(),
            "{name}: display_span"
        );
        assert_eq!(r.quarter().unwrap().name(), e["quarter"], "{name}: quarter");
        assert_eq!(r.combined_form().unwrap(), e["written"], "{name}: written");
        assert_eq!(
            r.span_form().unwrap(),
            e["written_span"],
            "{name}: written_span"
        );
    }
}

#[test]
fn every_duration_passes() {
    let file: Value = serde_json::from_str(VECTORS).unwrap();
    let durations = file["durations"].as_array().unwrap();
    assert!(!durations.is_empty());
    for v in durations {
        let name = v["name"].as_str().unwrap();
        let from = Instant::parse_rfc3339(v["from"].as_str().unwrap()).unwrap();
        let to = Instant::parse_rfc3339(v["to"].as_str().unwrap()).unwrap();
        let d = SolarDuration::between(
            from,
            to,
            v["lat"].as_f64().unwrap(),
            v["lon"].as_f64().unwrap(),
        );
        let e = &v["expected"];
        seconds_within(name, "seconds", d.seconds, &e["seconds"]);
        assert_eq!(
            d.display_ks_steps() as f64 / 10.0,
            e["display_ks"].as_f64().unwrap(),
            "{name}: display_ks"
        );
        match e["spans"].as_f64() {
            Some(spans) => {
                let actual = d.spans.unwrap_or_else(|| panic!("{name}: no spans"));
                assert!((actual - spans).abs() <= 0.001, "{name}: spans {actual}");
                assert_eq!(
                    d.display_spans().unwrap(),
                    e["display_spans"].as_i64().unwrap(),
                    "{name}: display_spans"
                );
            }
            None => assert!(d.spans.is_none(), "{name}: spans across a polar day"),
        }
    }
}

fn instant_within(name: &str, field: &str, actual: Instant, expected: &Value) {
    let expected = Instant::parse_rfc3339(expected.as_str().unwrap()).unwrap();
    let diff = actual - expected;
    assert!(diff.abs() <= 1.0, "{name}: {field} off by {diff} s");
}

fn seconds_within(name: &str, field: &str, actual: f64, expected: &Value) {
    let diff = actual - expected.as_f64().unwrap();
    assert!(diff.abs() <= 1.0, "{name}: {field} off by {diff} s");
}
